const BASE_URL = '';
$host = 'localhost'; $db = 'db_mundial2026'; $user = 'root'; $pass = '';
$pdo = null; $dbError = '';
try { $pdo = new PDO("mysql:host=$host;dbname=$db;charset=utf8mb4", $user, $pass, [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]); }
catch (Throwable $e) { $dbError = 'No se pudo conectar a MySQL. Importa db_mundial2026.sql y revisa la configuración de conexión.'; }
function e($v){ return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function go($url='?'){ header('Location: '.$url); exit; }
if (!isset($_SESSION['csrf'])) $_SESSION['csrf'] = bin2hex(random_bytes(24));
function csrf(){ return '<input type="hidden" name="csrf" value="'.e($_SESSION['csrf']).'">'; }
function verifyCsrf(){ if (!hash_equals($_SESSION['csrf'] ?? '', $_POST['csrf'] ?? '')) { http_response_code(403); exit('Solicitud no válida. Vuelve atrás e inténtalo de nuevo.'); } }
$page = $_GET['page'] ?? 'dashboard';
$allowed = ['dashboard','jugadores','equipos','sedes','partidos']; if (!in_array($page,$allowed,true)) $page='dashboard';
$flash = $_SESSION['flash'] ?? ''; unset($_SESSION['flash']);
if ($pdo && $_SERVER['REQUEST_METHOD']==='POST') {
  verifyCsrf(); $action=$_POST['action']??'';
  try {
    if ($action==='save_player') {
      $id=(int)($_POST['id']??0); $name=trim($_POST['jugador']??''); $pos=trim($_POST['posicion']??''); $shirt=(int)($_POST['dorsal']??0); $age=(int)($_POST['edad']??0); $club=trim($_POST['club']??''); $team=(int)($_POST['equipo_id']??0);
      if (!$name||!$pos||!$club||$team<1) throw new RuntimeException('Completa todos los campos obligatorios.');
      if ($id) { $s=$pdo->prepare('UPDATE jugadores SET jugador=?,posicion=?,dorsal=?,edad=?,club=?,equipo_id=? WHERE idJugador=?'); $s->execute([$name,$pos,$shirt?:null,$age?:null,$club,$team,$id]); $_SESSION['flash']='Jugador actualizado correctamente.'; }
      else { $s=$pdo->prepare('INSERT INTO jugadores (jugador,posicion,dorsal,edad,club,equipo_id) VALUES (?,?,?,?,?,?)'); $s->execute([$name,$pos,$shirt?:null,$age?:null,$club,$team]); $_SESSION['flash']='Jugador registrado correctamente.'; }
      go('?page=jugadores');
    }
    if ($action==='delete_player') { $s=$pdo->prepare('DELETE FROM jugadores WHERE idJugador=?'); $s->execute([(int)$_POST['id']]); $_SESSION['flash']='Jugador eliminado.'; go('?page=jugadores'); }
    if ($action==='save_team') { $id=(int)($_POST['id']??0); $name=trim($_POST['equipo']??''); $group=trim($_POST['grupo']??''); $conf=trim($_POST['confederacion']??''); if(!$name||!$conf) throw new RuntimeException('Completa nombre y confederación.'); if($id){$s=$pdo->prepare('UPDATE equipos SET equipo=?,grupo=?,confederacion=? WHERE idEquipo=?');$s->execute([$name,$group?:null,$conf,$id]);}else{$s=$pdo->prepare('INSERT INTO equipos(equipo,grupo,confederacion) VALUES(?,?,?)');$s->execute([$name,$group?:null,$conf]);} $_SESSION['flash']='Equipo guardado correctamente.'; go('?page=equipos'); }
    if ($action==='delete_team') { $id=(int)$_POST['id']; $s=$pdo->prepare('SELECT COUNT(*) FROM jugadores WHERE equipo_id=?');$s->execute([$id]); if($s->fetchColumn()) throw new RuntimeException('No puedes eliminar un equipo que tiene jugadores registrados.'); $s=$pdo->prepare('DELETE FROM equipos WHERE idEquipo=?');$s->execute([$id]);$_SESSION['flash']='Equipo eliminado.';go('?page=equipos'); }
    if ($action==='save_venue') { $id=(int)($_POST['id']??0);$name=trim($_POST['sede']??'');$city=trim($_POST['ciudad']??'');$country=trim($_POST['pais']??'');$capacity=(int)($_POST['capacidad']??0);if(!$name||!$city||!$country||$capacity<1)throw new RuntimeException('Revisa los datos del estadio.');if($id){$s=$pdo->prepare('UPDATE sedes SET sede=?,ciudad=?,pais=?,capacidad=? WHERE idSede=?');$s->execute([$name,$city,$country,$capacity,$id]);}else{$s=$pdo->prepare('INSERT INTO sedes(sede,ciudad,pais,capacidad) VALUES(?,?,?,?)');$s->execute([$name,$city,$country,$capacity]);}$_SESSION['flash']='Sede guardada correctamente.';go('?page=sedes'); }
    if ($action==='delete_venue') { $s=$pdo->prepare('DELETE FROM sedes WHERE idSede=?');$s->execute([(int)$_POST['id']]);$_SESSION['flash']='Sede eliminada.';go('?page=sedes'); }
    if ($action==='save_match') { $id=(int)($_POST['id']??0);$phase=trim($_POST['fase']??'Fase de grupos');$date=$_POST['fecha']??'';$venue=(int)($_POST['sede_id']??0);$home=(int)($_POST['equipo_local_id']??0);$away=(int)($_POST['equipo_visitante_id']??0);$gh=max(0,(int)($_POST['goles_local']??0));$ga=max(0,(int)($_POST['goles_visitante']??0));$status=trim($_POST['estado']??'Programado');if(!$date||!$home||!$away||$home===$away)throw new RuntimeException('Selecciona fecha y dos equipos distintos.');if($id){$s=$pdo->prepare('UPDATE partidos SET fase=?,fecha=?,sede_id=?,equipo_local_id=?,equipo_visitante_id=?,goles_local=?,goles_visitante=?,estado=? WHERE idPartido=?');$s->execute([$phase,str_replace('T',' ',$date).(strlen($date)===16?':00':''),$venue?:null,$home,$away,$gh,$ga,$status,$id]);}else{$s=$pdo->prepare('INSERT INTO partidos(fase,fecha,sede_id,equipo_local_id,equipo_visitante_id,goles_local,goles_visitante,estado) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$phase,str_replace('T',' ',$date).(strlen($date)===16?':00':''),$venue?:null,$home,$away,$gh,$ga,$status]);}$_SESSION['flash']='Partido guardado correctamente.';go('?page=partidos'); }
    if ($action==='delete_match') { $s=$pdo->prepare('DELETE FROM partidos WHERE idPartido=?');$s->execute([(int)$_POST['id']]);$_SESSION['flash']='Partido eliminado.';go('?page=partidos'); }
  } catch(Throwable $ex) { $_SESSION['flash']=$ex instanceof RuntimeException?$ex->getMessage():'No se pudo guardar. Comprueba los datos y las relaciones.'; go('?page='.$page); }
}
$counts=['jugadores'=>0,'equipos'=>0,'sedes'=>0,'partidos'=>0]; $players=[];$teams=[];$venues=[];$matches=[];$edit=null;
if($pdo){try{foreach($counts as $k=>$_){$table=['jugadores'=>'jugadores','equipos'=>'equipos','sedes'=>'sedes','partidos'=>'partidos'][$k];$counts[$k]=(int)$pdo->query("SELECT COUNT(*) FROM $table")->fetchColumn();}
$teams=$pdo->query('SELECT * FROM equipos ORDER BY equipo')->fetchAll();$venues=$pdo->query('SELECT * FROM sedes ORDER BY sede')->fetchAll();
if($page==='jugadores'){$q=trim($_GET['q']??'');$s=$pdo->prepare('SELECT j.*,e.equipo,e.grupo FROM jugadores j JOIN equipos e ON e.idEquipo=j.equipo_id WHERE j.jugador LIKE ? OR j.club LIKE ? OR e.equipo LIKE ? ORDER BY j.idJugador DESC');$like="%$q%";$s->execute([$like,$like,$like]);$players=$s->fetchAll();if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM jugadores WHERE idJugador=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch()?:null;}}
if($page==='equipos'){$teams=$pdo->query('SELECT e.*,COUNT(j.idJugador) jugadores FROM equipos e LEFT JOIN jugadores j ON j.equipo_id=e.idEquipo GROUP BY e.idEquipo ORDER BY e.equipo')->fetchAll();if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM equipos WHERE idEquipo=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch()?:null;}}
if($page==='sedes'&&isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM sedes WHERE idSede=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch()?:null;}
if($page==='partidos'){$matches=$pdo->query('SELECT p.*,l.equipo local,v.equipo visitante,s.sede,s.ciudad FROM partidos p JOIN equipos l ON l.idEquipo=p.equipo_local_id JOIN equipos v ON v.idEquipo=p.equipo_visitante_id LEFT JOIN sedes s ON s.idSede=p.sede_id ORDER BY p.fecha')->fetchAll();if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM partidos WHERE idPartido=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch()?:null;}}
} catch(Throwable $ex){$dbError='La base de datos existe, pero sus tablas no coinciden con la versión esperada. Importa nuevamente db_mundial2026.sql.';}}
