<div class="modal-backdrop" id="teamModal"><div class="modal"><div class="modal-head"><div><span class="eyebrow dark-eyebrow">EQUIPOS</span><h2><?=($page==='equipos'&&$edit)?'Editar selección':'Nueva selección'?></h2></div><button class="modal-close" onclick="closeModal('teamModal')">×</button></div><form method="post"><?=csrf()?><input type="hidden" name="action" value="save_team"><input type="hidden" name="id" value="<?=e($edit['idEquipo']??'')?>"><div class="form-grid"><label class="full">Nombre de la selección<input name="equipo" required value="<?=e($edit['equipo']??'')?>" placeholder="Ej. Brasil"></label><label>Grupo<input name="grupo" maxlength="1" value="<?=e($edit['grupo']??'')?>" placeholder="A"></label><label>Confederación<select name="confederacion" required><?php foreach(['CONMEBOL','CONCACAF','UEFA','CAF','AFC','OFC'] as $v):?><option <?=($edit['confederacion']??'')===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></label></div><div class="modal-footer"><button type="button" class="btn btn-light" onclick="closeModal('teamModal')">Cancelar</button><button class="btn btn-primary">Guardar selección</button></div></form></div></div>
<div class="modal-backdrop" id="venueModal"><div class="modal"><div class="modal-head"><div><span class="eyebrow dark-eyebrow">INFRAESTRUCTURA</span><h2><?=($page==='sedes'&&$edit)?'Editar sede':'Nueva sede'?></h2></div><button class="modal-close" onclick="closeModal('venueModal')">×</button></div><form method="post"><?=csrf()?><input type="hidden" name="action" value="save_venue"><input type="hidden" name="id" value="<?=e($edit['idSede']??'')?>"><div class="form-grid"><label class="full">Nombre del estadio<input name="sede" required value="<?=e($edit['sede']??'')?>" placeholder="Ej. Estadio Azteca"></label><label>Ciudad<input name="ciudad" required value="<?=e($edit['ciudad']??'')?>"></label><label>País<input name="pais" required value="<?=e($edit['pais']??'')?>"></label><label class="full">Capacidad<input type="number" name="capacidad" min="1" required value="<?=e($edit['capacidad']??'')?>"></label></div><div class="modal-footer"><button type="button" class="btn btn-light" onclick="closeModal('venueModal')">Cancelar</button><button class="btn btn-primary">Guardar sede</button></div></form></div></div>
<div class="modal-backdrop" id="matchModal"><div class="modal"><div class="modal-head"><div><span class="eyebrow dark-eyebrow">CALENDARIO</span><h2><?=($page==='partidos'&&$edit)?'Editar partido':'Programar partido'?></h2></div><button class="modal-close" onclick="closeModal('matchModal')">×</button></div><form method="post"><?=csrf()?><input type="hidden" name="action" value="save_match"><input type="hidden" name="id" value="<?=e($edit['idPartido']??'')?>"><div class="form-grid"><label>Fase<select name="fase"><?php foreach(['Fase de grupos','Dieciseisavos','Octavos de final','Cuartos de final','Semifinal','Tercer puesto','Final'] as $v):?><option <?=($edit['fase']??'Fase de grupos')===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label>Fecha y hora<input type="datetime-local" name="fecha" required value="<?=e(isset($edit['fecha'])?date('Y-m-d\TH:i',strtotime($edit['fecha'])):'')?>"></label><label>Equipo local<select name="equipo_local_id" required><option value="">Seleccionar</option><?php foreach($teams as $t):?><option value="<?=$t['idEquipo']?>" <?=((int)($edit['equipo_local_id']??0)===(int)$t['idEquipo'])?'selected':''?>><?=e($t['equipo'])?></option><?php endforeach;?></select></label><label>Equipo visitante<select name="equipo_visitante_id" required><option value="">Seleccionar</option><?php foreach($teams as $t):?><option value="<?=$t['idEquipo']?>" <?=((int)($edit['equipo_visitante_id']??0)===(int)$t['idEquipo'])?'selected':''?>><?=e($t['equipo'])?></option><?php endforeach;?></select></label><label class="full">Estadio<select name="sede_id"><option value="">Sede por definir</option><?php foreach($venues as $v):?><option value="<?=$v['idSede']?>" <?=((int)($edit['sede_id']??0)===(int)$v['idSede'])?'selected':''?>><?=e($v['sede'].' · '.$v['ciudad'])?></option><?php endforeach;?></select></label><label>Goles local<input type="number" name="goles_local" min="0" value="<?=e($edit['goles_local']??0)?>"></label><label>Goles visitante<input type="number" name="goles_visitante" min="0" value="<?=e($edit['goles_visitante']??0)?>"></label><label class="full">Estado<select name="estado"><?php foreach(['Programado','En juego','Finalizado','Suspendido'] as $v):?><option <?=($edit['estado']??'Programado')===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></label></div><div class="modal-footer"><button type="button" class="btn btn-light" onclick="closeModal('matchModal')">Cancelar</button><button class="btn btn-primary">Guardar partido</button></div></form></div></div>
<script src="public/js/app.js"></script><?php if($edit && in_array($page,['jugadores','equipos','sedes','partidos'],true)):?><script>openModal('<?=['jugadores'=>'playerModal','equipos'=>'teamModal','sedes'=>'venueModal','partidos'=>'matchModal'][$page]?>');</script><?php endif;?></body></html>
